'use strict';const {app,BrowserWindow}=require('electron'),fs=require('node:fs'),path=require('node:path'),os=require('node:os');const root=path.resolve(__dirname,'../..'),temp=fs.mkdtempSync(path.join(os.tmpdir(),'villawolf-ui-test-'));app.setPath('userData',temp);app.commandLine.appendSwitch('disable-gpu');const errors=[];function window(){const w=new BrowserWindow({show:false,width:1100,height:850,webPreferences:{offscreen:true,contextIsolation:true,nodeIntegration:false,sandbox:true,preload:path.join(root,'tests/fixtures/estabilizacion-preload.cjs')}});w.webContents.on('console-message',(_e,details,message)=>{const level=details&&typeof details==='object'?details.level:details;if(level==='error'||level===3)errors.push(details&&typeof details==='object'?details.message:message);});return w;}
app.whenReady().then(async()=>{const admin=window();await admin.loadFile(path.join(root,'tools/admin-modpack/index.html'));await new Promise(r=>setTimeout(r,250));let state=await admin.webContents.executeJavaScript(`({createVisible:!document.getElementById('wizardEntry').hidden,redundant:!!document.getElementById('adminOpenFiles')})`);if(!state.createVisible||state.redundant)throw Error('Vista principal incorrecta');await admin.webContents.executeJavaScript(`document.getElementById('adminPackChoice').value='test-pack';document.getElementById('adminPackChoice').dispatchEvent(new Event('change'));`);await new Promise(r=>setTimeout(r,100));state=await admin.webContents.executeJavaScript(`({createHidden:document.getElementById('wizardEntry').hidden,menusVisible:!document.getElementById('adminEditorMenus').hidden})`);if(!state.createHidden||!state.menusVisible)throw Error('Edición incorrecta');await admin.webContents.executeJavaScript(`document.getElementById('adminProfileButton').click()`);state=await admin.webContents.executeJavaScript(`({selectorHidden:document.getElementById('adminPackChoice').hidden,menusHidden:document.getElementById('adminEditorMenus').hidden,closeVisible:document.getElementById('closeAdminMenu').getClientRects().length>0})`);if(!state.selectorHidden||!state.menusHidden||!state.closeVisible)throw Error('Perfil superpuesto');await admin.webContents.executeJavaScript(`document.getElementById('closeAdminMenu').click();document.getElementById('adminOpenWizard').click();`);await new Promise(r=>setTimeout(r,100));state=await admin.webContents.executeJavaScript(`({wizard:!document.getElementById('createLauncherWizard').hidden,libraryHidden:document.getElementById('adminLibrary').hidden})`);if(!state.wizard||!state.libraryHidden)throw Error('Asistente superpuesto');await admin.webContents.executeJavaScript(`document.getElementById('wizardClose').click()`);await new Promise(r=>setTimeout(r,100));state=await admin.webContents.executeJavaScript(`({createVisible:!document.getElementById('wizardEntry').hidden,wizardHidden:document.getElementById('createLauncherWizard').hidden})`);if(!state.createVisible||!state.wizardHidden)throw Error('No vuelve a principal');const bot=window();await bot.loadFile(path.join(root,'auth-server/roles-bot/index.html'));await new Promise(r=>setTimeout(r,100));state=await bot.webContents.executeJavaScript(`({connection:document.getElementById('status').textContent,ping:document.getElementById('connection-ping').textContent,roles:document.getElementById('roles-state').textContent,announcements:document.getElementById('announcements-state').textContent,history:document.getElementById('activity-text').value})`);if(state.connection!=='Conectado con Discord.'||state.ping!=='23 ms'||!state.roles.includes('pendientes')||!state.announcements.includes('pendientes')||!state.history.includes('Prueba aislada'))throw Error('Estados de bot mezclados');if(errors.length)throw Error('Errores de interfaz: '+errors.join(' | '));console.log('6 transiciones de interfaz y estados del Bot verificadas en Chromium aislado; sin credenciales ni red.');admin.destroy();bot.destroy();app.exit(0);}).catch(e=>{console.error(e.message);app.exit(1);});
